for a in applicants:
    print(f"\n{'='*50}")
    print(f"Registering: {a['name']} ({a['email']})")

    # 1. Register
    resp = httpx.post(f"{API}/auth/register", json={
        "name": a["name"], "email": a["email"], "phone": a["phone"], "password": a["password"]
    })
    token = resp.json().get("access_token")
    if not token:
        print(f"  Registration failed: {resp.json()}")
        continue
    headers = {"Authorization": f"Bearer {token}"}
    print(f"  Registered OK")

    # 2. Start application (draft)
    resp = httpx.post(f"{API}/candidates/start-application", headers=headers, json={"vacancy_id": a["vacancy_id"]})
    if resp.status_code != 200:
        print(f"  Start failed: {resp.json()}")
        continue
    print(f"  Draft created for vacancy {a['vacancy_id']}")

    # 3. Get questions
    v_resp = httpx.get(f"{API}/vacancies/{a['vacancy_id']}")
    questions = v_resp.json().get("questions", [])

    # 4. Save answers
    formatted = []
    for q in questions:
        answer_text = a["answers"].get(q["order"], ".")
        formatted.append({"question_id": q["id"], "question_text": q["text"], "answer_text": answer_text})

    resp = httpx.put(f"{API}/candidates/save-draft", headers=headers, json={"answers": formatted})
    answered = sum(1 for f in formatted if f["answer_text"] != ".")
    print(f"  Saved {answered}/{len(formatted)} answers")

    # 5. Upload ID document
    with open(ID_PHOTO, "rb") as f:
        resp = httpx.post(f"{API}/candidates/upload-id", headers=headers, files={"file": ("udo.jpg", f, "image/jpeg")})
    if resp.status_code == 200:
        print(f"  ID uploaded: {resp.json().get('id_document_url')}")
    else:
        print(f"  ID upload failed: {resp.status_code}")

    # 6. Submit application → triggers AI detection + Celery LLM analysis
    try:
        resp = httpx.post(f"{API}/candidates/submit-application", headers=headers, timeout=300.0)
        if resp.status_code == 200:
            print(f"  SUBMITTED! {resp.json()}")
        else:
            print(f"  Submit failed: {resp.status_code} {resp.text[:100]}")
    except httpx.ReadTimeout:
        print(f"  Submit sent (timeout waiting for AI detection — processing in background)")

print(f"\n{'='*50}")
print("All done! AI detection + LLM analysis running in background via Celery.")
print("Check HR panel in ~1-2 minutes.")
